import { Injectable } from '@angular/core';
import {RaumBasisDaten, RaumService} from '../../pages/invent-form/data-services/raum.service';
import {ImageBaseData, ImagesService} from '../../pages/invent-form/data-services/images.service';
import {DexieService} from './dexie.service';
import {BasedataService} from './basedata.service';

@Injectable({
  providedIn: 'root'
})
export class DummieSeederService {

  private baseImage: ImageBaseData;
  constructor(
    private dexie: DexieService,
    private raumService: RaumService,
    private imageService: ImagesService,
    private baseData: BasedataService
  ) {
    this.baseImage = { type: 'image/jpeg',
      name: 'TEST',
      desc: 'TEST',
      width: 340,
      height: 453,
      size: 163855,
      mcuuid: '',
      gcuuid: '',
      // tslint:disable-next-line:max-line-length
      data_url: 'data:image/jpeg;base64,'
    };
  }

  async createRaeumeAndImages(
    raumBaseData: RaumBasisDaten,
    numRaeume: number,
    numImages: number,
    useJobid?: number
  ): Promise<number> {
    const jobid = useJobid || this.baseData.getCurrentJobid();
    const invGebItem = await this.dexie.inventurenGebaeude.where({jobid}).first();
    const gid = invGebItem.gid;
    const d = new Date();
    const sd = d.getUTCDate();
    const etgPrefix = 'TEST-' + sd;
    const rb = raumBaseData;
    const ib = this.baseImage;
    ib.for_jobid = jobid;
    const maxNumRoomDigits = numRaeume.toString(10).length;
    const maxNumImgDigits = numImages.toString(10).length;
    rb.gid = gid;
    if (!rb.Raum) {
      rb.Raum = 'TEST TEST ';
      rb.Raumbezeichnung = 'NUR EIN TEST! NUR EIN TEST!';
    }
    if (!rb.Etage) {
      rb.Etage = etgPrefix;
    }
    const withImages = numImages > 0;
    const modPerRoom = !withImages ? 0 : numImages % numRaeume;
    const minPerRoom = !withImages ? 0 : Math.floor(numImages / numRaeume);
    const maxPerRoom = !withImages ? 0 : Math.ceil(numImages / numRaeume);
    const maxInterval = !withImages ? 0 : Math.floor(numRaeume / modPerRoom);
    let countAddedRooms = 0;
    let countAddedImgs = 0;

    for (let ri = 0; ri < numRaeume; ri++) {
      const rData = {... rb};
      rData.Raum += ri.toString(10).padStart(maxNumRoomDigits, '0');
      console.log('Add ' + (ri + 1) + ' Dummie-Room');
      const rResult = await this.raumService.insert(rData, jobid);
      if (!rResult.success) {
        const error = 'ERROR ON CREATING Room-Dummie-DATA!\n' +
          'ADDED Rooms: ' + countAddedRooms.toString(10) + '\n' +
          'ADDED Images: ' + countAddedImgs.toString(10) + '\n' +
          (rResult.errorMsg || '');
        console.error(error, { rData });
        if (typeof alert === 'function') {
          alert(error);
        }
        return;
      }
      ++countAddedRooms;

      if (countAddedImgs < numImages) {
        const addNumImages = (maxInterval <= 1 || ri % maxInterval !== 0) ? minPerRoom : maxPerRoom;
        for (let ii = 0; ii < addNumImages; ii++) {
          const iData = {... ib};
          iData.name += (1 + countAddedImgs + ii).toString(10).padStart(maxNumImgDigits, '0');
          console.log('Add ' + (1 + countAddedImgs + ii) + ' Dummie-Room-Image');
          const iUUID = await this.imageService.insertRaumImage(iData, rResult.newItem.uuid);
          if (!iUUID) {
            const error = 'ERROR ON CREATING RoomImage-Dummie-DATA!\n' +
              'ADDED Rooms: ' + countAddedRooms.toString(10) + '\n' +
              'ADDED Images: ' + countAddedImgs.toString(10) + '\n';
            console.error(error, { iData });
            if (typeof alert === 'function') {
              alert(error);
            }
            return;
          }
          ++countAddedImgs;
        }
      }
    }

    const msg = 'FINISHED CREATING Room-/Image-Dummie-DATA!\n' +
      'ADDED Rooms: ' + countAddedRooms.toString(10) + '\n' +
      'ADDED Images: ' + countAddedImgs.toString(10) + '\n';
    console.log(msg);
    if (typeof alert === 'function') {
      alert(msg);
    }

    return countAddedRooms + countAddedImgs;
  }
}
